const originalText=new WeakMap();
function translateDataValue(v){return translateText(v);}
function apply(root=document){
  const scope=root.querySelectorAll?root:document;
  scope.querySelectorAll('[data-i18n]').forEach(el=>{el.textContent=t(el.dataset.i18n);});
  scope.querySelectorAll('[data-i18n-html]').forEach(el=>{el.innerHTML=t(el.dataset.i18nHtml);});
  scope.querySelectorAll('[data-i18n-placeholder]').forEach(el=>{el.placeholder=t(el.dataset.i18nPlaceholder);});
  const selector=scope.querySelector?.('#language-select');if(selector)selector.value=current;
  autoTranslate(scope);
}
function autoTranslate(root=document){
  const skip='SCRIPT,STYLE,NOSCRIPT';
  const walker=document.createTreeWalker(root.body||root,NodeFilter.SHOW_TEXT);
  const nodes=[];let n;
  while((n=walker.nextNode())){
    const p=n.parentElement;
    if(!p||p.closest(skip)||p.dataset.i18nIgnore==='true'||p.closest('[data-i18n],[data-i18n-html]'))continue;
    if(!originalText.has(n))originalText.set(n,n.nodeValue);
    const base=originalText.get(n);
    const s=normalize(base);
    if(s)nodes.push([n,base,s]);
  }
  nodes.forEach(([n,base,s])=>{
    n.nodeValue=current==='en'?base:(tr[current]?.[s]?base.replace(s,tr[current][s]):base);
  });
  document.querySelectorAll('input[placeholder],textarea[placeholder],input[type="button"],input[type="submit"],option,[title],[aria-label]').forEach(el=>{
    if(el.dataset.i18nIgnore==='true')return;
    if((el.tagName==='INPUT') && (el.type==='button'||el.type==='submit')){
      if(!el.dataset.i18nOriginalValue)el.dataset.i18nOriginalValue=el.value;
      const base=el.dataset.i18nOriginalValue;
      el.value=current==='en'?base:(tr[current]?.[normalize(base)]||base);
    }
    if(el.placeholder){
      if(!el.dataset.i18nOriginalPlaceholder)el.dataset.i18nOriginalPlaceholder=el.placeholder;
      const base=el.dataset.i18nOriginalPlaceholder;
      el.placeholder=current==='en'?base:(tr[current]?.[normalize(base)]||base);
    }
    if(el.title){
      if(!el.dataset.i18nOriginalTitle)el.dataset.i18nOriginalTitle=el.title;
      const base=el.dataset.i18nOriginalTitle;
      el.title=current==='en'?base:(tr[current]?.[normalize(base)]||base);
    }
    const aria=el.getAttribute('aria-label');
    if(aria){
      if(!el.dataset.i18nOriginalAria)el.dataset.i18nOriginalAria=aria;
      const base=el.dataset.i18nOriginalAria;
      el.setAttribute('aria-label',current==='en'?base:(tr[current]?.[normalize(base)]||base));
    }
    if(el.tagName==='OPTION'){
      if(!el.dataset.i18nOriginalText)el.dataset.i18nOriginalText=el.textContent;
      const base=el.dataset.i18nOriginalText;
      el.textContent=current==='en'?base:(tr[current]?.[normalize(base)]||base);
    }
  });
}
function setLanguage(code){if(!languages[code])return;current=code;localStorage.setItem('society360-language',code);document.documentElement.lang=code;safeApply();window.dispatchEvent(new CustomEvent('society360-language-changed',{detail:{code}}));}
const api={languages,t,english:key=>keys[key]||key,setLanguage,get current(){return current;},locale:()=>languages[current].locale,init:()=>safeApply(),apply:safeApply,translateText,translateDataValue};
window.Society360I18n=api;
window.addEventListener('society360-language-changed',()=>safeApply());
document.addEventListener('change',e=>{if(e.target?.id==='language-select')setLanguage(e.target.value);});
let applying=false;
let observerTimer=0;
const dynamicObserver=new MutationObserver(mutations=>{
  if(applying)return;
  if(!mutations.some(m=>m.addedNodes&&m.addedNodes.length))return;
  clearTimeout(observerTimer);
  observerTimer=setTimeout(()=>safeApply(),50);
});
function safeApply(root=document){
  if(applying)return;
  applying=true;
  try{apply(root);}finally{applying=false;}
}
if(document.body)dynamicObserver.observe(document.body,{childList:true,subtree:true});
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>safeApply(),{once:true});else safeApply();

